answer = []
for source, meta in zip(sources, metadata, strict=True):
    obj = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    obj.update({
        'proposed_xml': Path(meta['file']).read_text().strip(),
        'reason': meta['reason'],
        'review_notes': meta['review_notes'],
        'status': 'rewrite_draft',
        'change_type': 'normative_reduction',
        'reform_policy_id': 'editorial_direction_2026_10_19',
        'removed_provisions': meta['removed_provisions'],
        'benefit_review': meta['benefit_review'],
    })
    source_key = source['code_id'] + '|' + source['source_id']
    obj['reference_checks'] = []
    for key in references['requirements'][source_key]:
        target = references['targets'][key]
        obj['reference_checks'].append({
            'target_key': key,
            'view_sha256': target['view_sha256'],
            'assessment': meta['assessments'][target['number']],
        })
    answer.append(obj)

Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
